export type getProjectUsageResponse200 = {
  data: UsageReport;
  status: 200;
};

export type getProjectUsageResponse400 = {
  data: ErrorResponse;
  status: 400;
};

export type getProjectUsageResponse401 = {
  data: N401Response;
  status: 401;
};

export type getProjectUsageResponse403 = {
  data: N403Response;
  status: 403;
};

export type getProjectUsageResponse500 = {
  data: N500Response;
  status: 500;
};

export type getProjectUsageResponseSuccess = getProjectUsageResponse200 & {
  headers: Headers;
};
export type getProjectUsageResponseError = (
  | getProjectUsageResponse400
  | getProjectUsageResponse401
  | getProjectUsageResponse403
  | getProjectUsageResponse500
) & {
  headers: Headers;
};

export type getProjectUsageResponse =
  getProjectUsageResponseSuccess | getProjectUsageResponseError;

export const getGetProjectUsageUrl = (
  projectId: string,
  params?: GetProjectUsageParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/elitea_core/usage/prompt_lib/${projectId}/usage?${stringifiedParams}`
    : `/elitea_core/usage/prompt_lib/${projectId}/usage`;
};

/**
 * Backs Settings → Usage. The period is the current calendar month and is
 * reported back in `period_start`, `period_end` and `resets_at`, so no
 * date range is accepted.
 *
 * `scope=project` reports the whole project; `scope=user` reports only the
 * calling member's own budget within it.
 *
 * The dimensional views — `daily`, `models` and the token totals — come
 * from the per-request usage ledger added by issue #320. They are ABSENT,
 * not empty, when the ledger holds no row for the scope in this period:
 * an empty series reads as "no calls were made", which is a different and
 * wrong claim about a deployment upgraded part-way through a period.
 * `usage_events_available` says which case the payload is in, exactly as
 * `spend_available` distinguishes "no spend yet" from "no data".
 *
 * A member who may not see platform cost figures receives the same payload
 * with `monthly_limit`, `effective_limit`, `spend`, `remaining` and
 * `currency` REMOVED and `can_see_amounts: false`; the `spend` inside each
 * `daily` and `models` row is removed too, because leaving the same money
 * in a per-day series would make the control decorative. Percentages, the
 * warning threshold, the period and the token counts are still present, so
 * the usage bar and the charts still render. Project admins, and the owner
 * of a personal project, see the amounts.
 * @summary Current-period usage against the applicable budget
 */
export const getProjectUsage = async (
  projectId: string,
  params?: GetProjectUsageParams,
  options?: Parameters<typeof eliteaFetch>[1],
): Promise<getProjectUsageResponse> => {
  return eliteaFetch<getProjectUsageResponse>(
    getGetProjectUsageUrl(projectId, params),
    {
      ...options,
      method: "GET",
    },
  );
};

export const getGetProjectUsageQueryKey = (
  projectId: string,
  params?: GetProjectUsageParams,
) => {
  return [
    `/elitea_core/usage/prompt_lib/${projectId}/usage`,
    ...(params ? [params] : []),
  ] as const;
};

export const getGetProjectUsageQueryOptions = <
  TData = Awaited<ReturnType<typeof getProjectUsage>>,
  TError = ErrorResponse | N401Response | N403Response | N500Response,
>(
  projectId: string,
  params?: GetProjectUsageParams,
  options?: {
    query?: Partial<
      UseQueryOptions<
        Awaited<ReturnType<typeof getProjectUsage>>,
        TError,
        TData
      >
    >;
    request?: SecondParameter<typeof eliteaFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getGetProjectUsageQueryKey(projectId, params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getProjectUsage>>> = ({
    signal,
  }) => getProjectUsage(projectId, params, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: projectId !== null && projectId !== undefined,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof getProjectUsage>>,
    TError,
    TData
  > & { queryKey: DataTag<QueryKey, TData, TError> };
};

